// app/root.jsx DEPOIS: nenhum script do App Bridge aqui.
// O AppProvider (app/routes/app.jsx) injeta o script com data-api-key.
<head>
  <meta charSet="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <Meta />
  <Links />
</head>

// app/routes/app.jsx: o único lugar que carrega o App Bridge
import { AppProvider } from "@shopify/shopify-app-remix/react";
import { NavMenu } from "@shopify/app-bridge-react";
// o mesmo CSS da loja: o preview do admin fica idêntico ao storefront
import badgeStyles from "../../extensions/flags/assets/flags.css?url";

export const links = () => [
  { rel: "stylesheet", href: polarisStyles },
  { rel: "stylesheet", href: badgeStyles },
  { rel: "stylesheet", href: adminStyles },
];

export const loader = async ({ request }) => {
  await authenticate.admin(request);
  return json({ apiKey: process.env.SHOPIFY_API_KEY || "" });
};

export default function App() {
  const { apiKey } = useLoaderData();
  return (
    <AppProvider isEmbeddedApp apiKey={apiKey}>
      <NavMenu>
        <Link to="/app" rel="home">Início</Link>
        <Link to="/app/flags">Flags</Link>
        <Link to="/app/billing">Planos</Link>
      </NavMenu>
      <Outlet />
    </AppProvider>
  );
}
